"""Build the standalone coordination study from measured experiment results."""
from __future__ import annotations

import json
from pathlib import Path
from docx import Document
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml import OxmlElement
from docx.shared import Cm, Pt, RGBColor

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "deliverables"
OUT.mkdir(exist_ok=True)
rows = json.loads((ROOT / "experiments/results/summary.json").read_text(encoding="utf-8"))
paired = json.loads((ROOT / "experiments/results/paired.json").read_text(encoding="utf-8"))
lookup = {(x["scenario"], x["mechanism"]): x for x in rows}
delta = {x["scenario"]: x for x in paired}
doc = Document()
sec = doc.sections[0]
sec.page_width, sec.page_height = Cm(21), Cm(29.7)
sec.top_margin, sec.bottom_margin = Cm(2.0), Cm(1.9)
sec.left_margin, sec.right_margin = Cm(2.4), Cm(2.2)
normal = doc.styles["Normal"]
normal.font.name, normal.font.size = "Times New Roman", Pt(11)
normal.paragraph_format.space_after = Pt(6)
normal.paragraph_format.line_spacing = 1.12
for name, size in (("Title", 17), ("Heading 1", 14), ("Heading 2", 12)):
    style = doc.styles[name]
    style.base_style = normal
    style.font.name = "Times New Roman"
    style.font.size = Pt(size)
    style.font.bold = True
    style.font.color.rgb = RGBColor(0, 0, 0)
    style.paragraph_format.space_before = Pt(12)
    style.paragraph_format.space_after = Pt(6)
    style.paragraph_format.keep_with_next = True


def para(value: str, style: str | None = None):
    return doc.add_paragraph(value, style)


def heading(value: str):
    doc.add_heading(value, 1)


def table(headers: list[str], body: list[tuple[str, ...]]):
    obj = doc.add_table(rows=1, cols=len(headers))
    obj.style = "Table Grid"
    obj.alignment = WD_TABLE_ALIGNMENT.CENTER
    for cell, value in zip(obj.rows[0].cells, headers):
        cell.text = value
    for values in body:
        for cell, value in zip(obj.add_row().cells, values):
            cell.text = str(value)
    for row in obj.rows:
        row._tr.get_or_add_trPr().append(OxmlElement("w:cantSplit"))
        for cell in row.cells:
            for p in cell.paragraphs:
                for run in p.runs:
                    run.font.size = Pt(8.5)
    return obj


def figure(anchor: str, caption: str):
    p = para(anchor)
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.keep_with_next = True
    c = para(caption)
    c.alignment = WD_ALIGN_PARAGRAPH.CENTER
    c.paragraph_format.space_after = Pt(10)


title = para("Исследование механизмов распределения исследовательских задач в многоагентной системе ResearchRadar MAS", "Title")
title.alignment = WD_ALIGN_PARAGRAPH.CENTER
para("")
p = para("Коротаев Андрей Дмитриевич")
p.alignment = WD_ALIGN_PARAGRAPH.CENTER
p = para("Группа Б24-507")
p.alignment = WD_ALIGN_PARAGRAPH.CENTER
para("")
p = para("2026")
p.alignment = WD_ALIGN_PARAGRAPH.CENTER
doc.add_page_break()

heading("Аннотация")
para("Исследуется влияние централизованного назначения и контрактной сети на многозадачный научно-информационный поиск. Оба механизма работают с одними агентами, адаптерами и замороженными данными. Сравнение включает четыре условия нагрузки и отказа, по 12 парных повторов каждого условия. Измерены время исследования, число сообщений, задержка назначения и выполнение задач. При равномерной нагрузке различие во времени невелико, тогда как контрактная сеть создаёт больше сообщений. При скрытой загрузке локальные заявки улучшают выбор исполнителя; при ограниченном составе их обмен добавляет задержку. Отдельно подтверждены сетевые адаптеры OpenAlex, Crossref, arXiv и Google News RSS и проверена ограниченная роль Qwen в формировании альтернативного запроса. Экспериментальные материалы синтетические и не служат оценкой достоверности найденных публикаций.")

heading("1. Исследовательская задача")
para("Один научный вопрос требует нескольких видов поиска: междисциплинарных публикаций, библиографических записей, препринтов и новостей. Исполнители различаются компетенциями и текущей загрузкой. Координатор должен назначать задачи так, чтобы не терять частичные результаты при отказе и не превращать обмен сообщениями в самоцель. Исследовательский вопрос состоит в том, как способ назначения меняет время, коммуникационную нагрузку и долю завершённых задач при одинаковых входных условиях.")
para("Проверялись две гипотезы. Первая: контрактная сеть увеличит число сообщений и время согласования при любом составе участников. Вторая: при скрытой от координатора загрузке заявки агентов могут уменьшить общее время, поскольку отражают их локальное состояние. Эти предположения были сформулированы до анализа сохранённых измерений; преимущества не предполагались для каждого сценария.")

heading("2. Архитектура исследовательского цикла")
para("Тема преобразуется в четыре независимые задачи: OpenAlex, Crossref, arXiv и новостной поиск. Проверенная альтернативная формулировка добавляет ещё один запрос OpenAlex. В рабочем цикле участвуют координатор и шесть поисковых исполнителей. Четыре агента имеют частично пересекающиеся научные компетенции, два — новостную. У каждого исполнителя собственная очередь, локальная оценка загрузки и последовательное выполнение принятых заданий. Он может принимать новые сообщения и предложения, пока предыдущая задача выполняется. Общие адаптеры источников не зависят от выбранного протокола.")
figure("FIGURE_ARCH", "Рисунок 1 — Общая архитектура распределения исследовательских задач")
para("Задачу задаёт кортеж t = (id, kind, query, limit). Состояние исполнителя хранит фазу idle/busy/stopped, число задач в очереди, успешные завершения, отказы и время занятости. Сообщение содержит отправителя, адресата, тип, ID исследования и задачи, полезную нагрузку и correlation_id. Шина разрешает только заранее заданные направления. Результат принимается лишь если отправитель и correlation_id совпадают с действующим назначением. Поздние и повторные сообщения учитываются отдельно.")

heading("3. Два механизма назначения")
para("Централизованный механизм выбирает доступного исполнителя по объявленной компетенции и оценке S_c = expected_ms × (1 + advertised_load + assigned_load). Здесь expected_ms — ожидаемая длительность в миллисекундах, advertised_load — известная координатору начальная загрузка, assigned_load — уже назначенные им незавершённые задачи. Минимальная оценка выигрывает, ничья разрешается по имени. Координатор отправляет одно сообщение task; исполнитель возвращает result или failure. Это полноценная политика с учётом нагрузки, а не назначение первого кандидата.")
para("В контрактной сети координатор рассылает CFP каждому подходящему агенту. Агент самостоятельно вычисляет S_a = expected_ms × (1 + private_load + queued), используя локальную загрузку и очередь, или отвечает отказом. Координатор собирает предложения до установленного срока, проверяет корреляцию, принимает минимальную заявку и отклоняет остальные. Победитель выполняет задачу. Такой протокол переносит оценку текущего состояния к исполнителю, но оплачивается дополнительным обменом сообщениями.")
figure("FIGURE_CNP", "Рисунок 2 — Последовательность сообщений контрактной сети для одной задачи")
para("При отказе выбранного исполнителя или истечении срока задача предлагается оставшимся кандидатам. После таймаута координатор отправляет cancel; ответ от прежнего назначения уже не может закрыть задачу. Общий срок исследования возвращает все готовые материалы и явно помечает незавершённые задания. Реальный HTTP-вызов, вынесенный в поток, завершается по собственному сетевому таймауту и не прерывается мгновенно отменой асинхронного ожидания.")

heading("4. Методика сравнения и данные")
para("Сравнивались четыре сценария: равномерная нагрузка, скрытая локальная загрузка двух исполнителей, ограниченный состав доступных агентов и отказ адаптера препринтов. В каждой паре оба механизма получают одну тему, пять задач, одинаковые компетенции, доступность, синтетические записи и управляемые задержки. Двенадцать seed меняют задержки в пределах ±10%; один seed используется для обоих механизмов. Всего выполнено 4 × 12 × 2 = 96 запусков. Замороженные записи помечены synthetic_fixture; данные LIVE-проверок в сравнение не включены.")
para("Общее время измеряется perf_counter от запуска менеджера до закрытия исполнителей и включает планирование потоков Python и ОС. Отдельно суммируется длительность выбора исполнителя для каждой задачи: для централизованного алгоритма это локальный расчёт, для контрактной сети — ожидание заявок и решение. При параллельных задачах сумма этих длительностей может перекрываться и не равна части общего времени. Коммуникационная стоимость измеряется числом действительно отправленных сообщений протокола, без служебного shutdown. Результативность — число завершённых задач из пяти. Разброс представлен стандартным отклонением по 12 повторам; парные разности рассчитаны из одинаковых seed. Малые синтетические задержки не позволяют переносить абсолютные миллисекунды на сетевую эксплуатацию.")

doc.add_page_break()
heading("5. Результаты эксперимента")
names = {"balanced": "Равномерная", "hidden_load": "Скрытая загрузка",
         "limited_availability": "Ограниченный состав", "source_failure": "Отказ источника"}
table(["Сценарий", "Механизм", "Время, мс", "Сообщения", "Задачи"], [
    (names[scenario], "Центр." if method == "centralized" else "Контр. сеть",
     f"{lookup[(scenario, method)]['wall_ms_mean']:.1f} ± {lookup[(scenario, method)]['wall_ms_sd']:.1f}",
     str(round(lookup[(scenario, method)]["messages_mean"])),
     f"{lookup[(scenario, method)]['completed_tasks_mean']:.0f}/5")
    for scenario in names for method in ("centralized", "contract-net")])
para("Таблица 1 — Средние значения и стандартное отклонение времени по 12 повторам; число сообщений и завершённых задач указано как среднее.")
figure("FIGURE_WALL", "Рисунок 3 — Среднее полное время исследования по сценариям")
figure("FIGURE_MESSAGES", "Рисунок 4 — Среднее число сообщений протокола")
figure("FIGURE_COORD", "Рисунок 5 — Суммарная задержка назначения по задачам")

heading("6. Интерпретация")
para(f"В равномерном сценарии средняя парная разность времени (контрактная сеть минус централизованный механизм) равна {delta['balanced']['wall_ms_difference_mean']:+.1f} мс. При этом число сообщений возрастает с 10 до 44, а суммарная задержка назначения — с {lookup[('balanced','centralized')]['coordination_ms_mean']:.2f} до {lookup[('balanced','contract-net')]['coordination_ms_mean']:.2f} мс. Доля успешных задач одинакова: 5/5. Небольшая разница wall-time на таком стенде не даёт основания объявлять одного победителя.")
para(f"При скрытой загрузке локальные заявки меняют выбор исполнителей: парная разность времени составляет {delta['hidden_load']['wall_ms_difference_mean']:+.1f} мс в пользу контрактной сети. Все 12 пар дали разность от {delta['hidden_load']['wall_ms_difference_min']:+.1f} до {delta['hidden_load']['wall_ms_difference_max']:+.1f} мс. В сценарии ограниченного состава результат обратный: контрактная сеть медленнее на {delta['limited_availability']['wall_ms_difference_mean']:+.1f} мс в среднем. Это объясняется последовательным ожиданием и иной очередностью назначений в небольшом доступном пуле; результат зависит от выбранных параметров модели задержек.")
para(f"При отказе источника обе политики завершают четыре задачи из пяти и дважды пытаются назначить отказавшую подзадачу. У централизованного механизма в среднем 12 сообщений, у контрактной сети — 48. Данные других источников сохраняются. Следовательно, в этом сценарии переговоры увеличивают коммуникационную цену, но не восстанавливают недоступный общий адаптер.")

heading("7. Поисковый контур и интеллектуальный план")
para("В отдельной сетевой проверке по теме multi agent systems OpenAlex, Crossref, arXiv и Google News RSS вернули по три записи. Это подтверждает получение метаданных в проверенной среде, но не научную истинность публикаций и не достоверность новостей. DOI и идентификаторы arXiv сохраняются; записи с одинаковым DOI объединяются с сохранением источников обнаружения, сходные названия без точного идентификатора не объединяются. RSS используется по умолчанию, GDELT остаётся необязательным после ранее наблюдавшегося ограничения частоты.")
para("Qwen выполняет конкретную интеллектуальную задачу до распределения: преобразует исходную тему в альтернативный научный поисковый запрос. Ответ принимается только как JSON с одним коротким полем alternative_query после программной проверки. Успешный LIVE-вызов сформировал запрос «applications and architectures of multi-agent systems in AI»; он добавил пятую задачу OpenAlex, и цикл завершился. Первый вызов дал пустой пользовательский текст, что потребовало ограничения режима рассуждения. Оба вызова прошли через бюджетируемый журнал. В массовом сравнении LLM не вызывалась: политики использовали один фиксированный запрос. Его качество отдельно не оценивалось.")

heading("8. Ограничения и воспроизводимость")
para("Эксперименты проверяют механизмы распределения на малом синтетическом корпусе и контролируемых задержках. Они не измеряют релевантность реальных результатов и не моделируют все вариации сетевого времени. Координатор остаётся единой точкой отказа, агентные заявки отражают приближённую оценку, а не будущую фактическую длительность. Защитные механизмы против подделки сообщений и конкуренции за общий бюджет не входят в проверенный контур. При сетевом отказе внешнего источника положительный результат другого адаптера нельзя приписывать отказавшему источнику.")
para("Исходные измерения находятся в experiments/results/raw.csv; агрегаты и парные разности — в summary.json и paired.json, параметры — в metadata.json, очищенные трассы — в traces/, исходный код стенда — в tools/run_experiments.py. Набор синтетических материалов — data/frozen_sources.json. Команда воспроизведения: py -3.14 tools/run_experiments.py --repeats 12. Время wall-clock может немного измениться при другой загрузке компьютера, но данные, seed, механизм и правила подсчёта остаются доступными для независимого пересчёта.")

heading("Заключение")
para("Оба механизма реализованы как явные протоколы на общей системе агентов и решают одинаковые исследовательские задачи. Централизованный выбор экономнее по числу сообщений. Контрактная сеть получает преимущество при скрытой локальной загрузке, но в малом или ограниченном пуле может увеличить время и всегда требует большего обмена. Отказы отдельных источников не уничтожают уже полученные материалы. Поэтому выбор протокола следует связывать с доступностью информации о загрузке, числом кандидатов и ценой согласования, а не с универсальным рейтингом алгоритмов.")

path = OUT / "ResearchRadar_MAS_Task_Allocation.docx"
